let cleanup=()=>{};
export function disposeSlider(){cleanup();cleanup=()=>{}};
export function mountSlider(root){disposeSlider();if(!root)return;const track=root.querySelector('.hero-track'),originals=[...track.children],dots=[...root.querySelectorAll('.slider-dot')],pause=root.querySelector('.slider-pause');const last=originals.at(-1).cloneNode(true),first=originals[0].cloneNode(true);last.setAttribute('aria-hidden','true');last.inert=true;first.setAttribute('aria-hidden','true');first.inert=true;track.prepend(last);track.append(first);let index=1,timer,hover=false,focus=false,manualPause=false,moving=false,pointer=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)');const listeners=[];const on=(target,event,fn)=>{target.addEventListener(event,fn);listeners.push(()=>target.removeEventListener(event,fn))};const active=()=>((index-1)%3+3)%3;function accessibility(){originals.forEach((slide,i)=>{slide.inert=i!==active();slide.setAttribute('aria-hidden',String(i!==active()));slide.setAttribute('role','group');slide.setAttribute('aria-roledescription','Ansicht');slide.setAttribute('aria-label',`${i+1} von 3`)});dots.forEach((dot,i)=>{dot.setAttribute('aria-pressed',String(i===active()));dot.classList.toggle('active',i===active())});root.dataset.slide=String(active()+1)}function stop(){clearTimeout(timer);timer=null}function schedule(){stop();if(!hover&&!focus&&!manualPause&&!document.hidden&&!reduced.matches)timer=setTimeout(()=>{timer=null;go(index+1)},5000)}function setPosition(animate){track.style.transition=animate&&!reduced.matches?'transform 650ms cubic-bezier(.22,.68,.2,1)':'none';track.style.transform=`translateX(-${index*100}%)`;accessibility()}function settle(){if(index===4){index=1;setPosition(false)}else if(index===0){index=3;setPosition(false)}moving=false;if(!timer)schedule()}function go(next){if(moving)return;stop();index=next;moving=!reduced.matches;setPosition(true);if(reduced.matches)settle();else schedule()}
on(track,'transitionend',event=>{if(event.target===track&&event.propertyName==='transform')settle()});on(root,'mouseenter',()=>{hover=true;stop()});on(root,'mouseleave',()=>{hover=false;schedule()});on(root,'focusin',event=>{focus=event.target.matches(':focus-visible');if(focus)stop();else schedule()});on(root,'focusout',event=>{if(!root.contains(event.relatedTarget)){focus=false;schedule()}});on(document,'visibilitychange',schedule);on(reduced,'change',()=>{setPosition(false);moving=false;schedule()});on(root.querySelector('.slider-prev'),'click',()=>go(index-1));on(root.querySelector('.slider-next'),'click',()=>go(index+1));dots.forEach((dot,i)=>on(dot,'click',()=>go(i+1)));on(pause,'click',()=>{manualPause=!manualPause;pause.textContent=manualPause?'▶':'Ⅱ';pause.setAttribute('aria-label',manualPause?'Automatischen Wechsel starten':'Automatischen Wechsel pausieren');schedule()});on(root,'keydown',event=>{if(event.target.matches('input,textarea,select'))return;if(event.key==='ArrowRight'){event.preventDefault();go(index+1)}if(event.key==='ArrowLeft'){event.preventDefault();go(index-1)}});let suppressClick=false;on(track,'pointerdown',event=>{if(event.pointerType==='mouse')return;pointer={x:event.clientX,y:event.clientY};stop()});on(track,'pointerup',event=>{if(!pointer)return;const dx=event.clientX-pointer.x,dy=event.clientY-pointer.y;pointer=null;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)){suppressClick=true;go(index+(dx<0?1:-1))}else schedule()});on(track,'pointercancel',()=>{pointer=null;schedule()});const blockClick=event=>{if(suppressClick){event.preventDefault();event.stopPropagation();suppressClick=false}};track.addEventListener('click',blockClick,true);setPosition(false);schedule();cleanup=()=>{stop();listeners.forEach(remove=>remove());track.removeEventListener('click',blockClick,true)};}
